import React, { useState } from 'react';
import './landing.css'; // Ajoutez un fichier CSS pour styliser la page

const Landing = () => {
  const [investment, setInvestment] = useState(0);
  const [sales, setSales] = useState([{ name: '', purchasePrice: 0, salePrice: 0 }]);
  const [rentals, setRentals] = useState([{ name: '', rentalPrice: 0, rentalCount: 0 }]);
  const [expenses, setExpenses] = useState([{ name: '', amount: 0 }]);
  const [salesProfit, setSalesProfit] = useState(0);
  const [rentalIncome, setRentalIncome] = useState(0);
  const [totalExpenses, setTotalExpenses] = useState(0);

  const handleAddSale = () => {
    setSales([...sales, { name: '', purchasePrice: 0, salePrice: 0 }]);
  };

  const handleAddRental = () => {
    setRentals([...rentals, { name: '', rentalPrice: 0, rentalCount: 0 }]);
  };

  const handleAddExpense = () => {
    setExpenses([...expenses, { name: '', amount: 0 }]);
  };

  const calculateSalesProfit = () => {
    const profit = sales.reduce(
      (acc, sale) => acc + (sale.salePrice - sale.purchasePrice),
      0
    );
    setSalesProfit(profit);
  };

  const calculateRentalIncome = () => {
    const income = rentals.reduce(
      (acc, rental) => acc + rental.rentalPrice * rental.rentalCount,
      0
    );
    setRentalIncome(income);
  };

  const calculateTotalExpenses = () => {
    const expensesTotal = expenses.reduce((acc, expense) => acc + expense.amount, 0);
    setTotalExpenses(expensesTotal);
  };

  return (
    <div className="container mt-5">
      <h1 className="text-center">💰 Gestion de l'Argent 💰</h1>
      <p className="text-center">
        Calculez vos profits ou pertes en fonction de vos investissements, ventes, locations et dépenses.
      </p>

      {/* Section Investissement */}
      <div className="mt-4 section">
        <h3>💵 Investissement</h3>
        <div className="form-group">
          <label>Montant total investi :</label>
          <input
            type="text"
            className="form-control"
            value={investment}
            onChange={(e) => setInvestment(parseFloat(e.target.value) || 0)}
            placeholder="Montant de l'investissement"
          />
        </div>
      </div>

      {/* Section Ventes */}
      <div className="mt-4 section">
        <h3>🛒 Ventes</h3>
        {sales.map((sale, index) => (
          <div key={index} className="mb-3">
            <input
              type="text"
              className="form-control mb-2"
              value={sale.name}
              onChange={(e) => {
                const newSales = [...sales];
                newSales[index].name = e.target.value;
                setSales(newSales);
              }}
              placeholder="Nom de l'article"
            />
            <input
              type="number"
              className="form-control mb-2"
              value={sale.purchasePrice}
              onChange={(e) => {
                const newSales = [...sales];
                newSales[index].purchasePrice = parseFloat(e.target.value) || 0;
                setSales(newSales);
              }}
              placeholder="Prix d'achat"
            />
            <input
              type="number"
              className="form-control"
              value={sale.salePrice}
              onChange={(e) => {
                const newSales = [...sales];
                newSales[index].salePrice = parseFloat(e.target.value) || 0;
                setSales(newSales);
              }}
              placeholder="Prix de vente"
            />
          </div>
        ))}
        <button className="btn btn-secondary" onClick={handleAddSale}>
          ➕ Ajouter une vente
        </button>
        <button className="btn btn-primary mt-2" onClick={calculateSalesProfit}>
          🧮 Calculer le profit des ventes
        </button>
        <p className="mt-2">Profit des ventes : {salesProfit} €</p>
      </div>

      {/* Section Locations */}
      <div className="mt-4 section">
        <h3>🎲 Locations</h3>
        {rentals.map((rental, index) => (
          <div key={index} className="mb-3">
            <input
              type="text"
              className="form-control mb-2"
              value={rental.name}
              onChange={(e) => {
                const newRentals = [...rentals];
                newRentals[index].name = e.target.value;
                setRentals(newRentals);
              }}
              placeholder="Nom du jouet"
            />
            <input
              type="number"
              className="form-control mb-2"
              value={rental.rentalPrice}
              onChange={(e) => {
                const newRentals = [...rentals];
                newRentals[index].rentalPrice = parseFloat(e.target.value) || 0;
                setRentals(newRentals);
              }}
              placeholder="Prix de location"
            />
            <input
              type="number"
              className="form-control"
              value={rental.rentalCount}
              onChange={(e) => {
                const newRentals = [...rentals];
                newRentals[index].rentalCount = parseFloat(e.target.value) || 0;
                setRentals(newRentals);
              }}
              placeholder="Nombre de locations"
            />
          </div>
        ))}
        <button className="btn btn-secondary" onClick={handleAddRental}>
          ➕ Ajouter une location
        </button>
        <button className="btn btn-primary mt-2" onClick={calculateRentalIncome}>
          🧮 Calculer les revenus des locations
        </button>
        <p className="mt-2">Revenus des locations : {rentalIncome} €</p>
      </div>

      {/* Section Dépenses */}
      <div className="mt-4 section">
        <h3>🍔 Dépenses</h3>
        {expenses.map((expense, index) => (
          <div key={index} className="mb-3">
            <input
              type="text"
              className="form-control mb-2"
              value={expense.name}
              onChange={(e) => {
                const newExpenses = [...expenses];
                newExpenses[index].name = e.target.value;
                setExpenses(newExpenses);
              }}
              placeholder="Nom de la dépense"
            />
            <input
              type="number"
              className="form-control"
              value={expense.amount}
              onChange={(e) => {
                const newExpenses = [...expenses];
                newExpenses[index].amount = parseFloat(e.target.value) || 0;
                setExpenses(newExpenses);
              }}
              placeholder="Montant de la dépense"
            />
          </div>
        ))}
        <button className="btn btn-secondary" onClick={handleAddExpense}>
          ➕ Ajouter une dépense
        </button>
        <button className="btn btn-primary mt-2" onClick={calculateTotalExpenses}>
          🧮 Calculer les dépenses totales
        </button>
        <p className="mt-2">Dépenses totales : {totalExpenses} €</p>
      </div>
    </div>
  );
};

export default Landing;
